import React, { useState } from 'react';
import { v4 as uuidv4 } from 'uuid';
import InvestigationEditModal from './InvestigationEditModal';
import InvestigationCasePage from './InvestigationCasePage';
import TypeManager from './TypeManager';

const STATUS_STYLES = {
  active: { color: '#2e7d5e', bg: '#e4f4ec', label: 'Active' },
  cold:   { color: '#7a6a52', bg: '#f0e8d8', label: 'Cold'   },
  closed: { color: '#8a8680', bg: '#f2f0ec', label: 'Closed' },
};

// helper — resolves type from the live invTypes list
const getInvType = (id, invTypes) =>
  invTypes.find(t => t.id === id) || { id, label: id, color: '#8a8680', bg: '#f2f0ec' };

// ── Case card ─────────────────────────────────────────────────────
function CaseCard({ inv, books, invTypes, onClick, compact }) {
  const invType = getInvType(inv.type, invTypes);
  const ss = STATUS_STYLES[inv.status] || STATUS_STYLES.active;
  const linkedBooks = books.filter(b => (inv.bookIds || []).includes(b.id));

  if (compact) {
    return (
      <div onClick={onClick}
        style={{ background: 'var(--paper-card)', border: '1px solid var(--paper-3)', borderLeft: `4px solid ${invType.color}`, borderRadius: 8, padding: '12px 16px', cursor: 'pointer', display: 'grid', gridTemplateColumns: '1fr auto', gap: 12, alignItems: 'center', transition: 'box-shadow 0.12s' }}
        onMouseEnter={e => { e.currentTarget.style.boxShadow = 'var(--shadow-sm)'; e.currentTarget.style.borderColor = invType.color + '66'; }}
        onMouseLeave={e => { e.currentTarget.style.boxShadow = 'none'; e.currentTarget.style.borderColor = 'var(--paper-3)'; }}>
        <div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 7, marginBottom: 3 }}>
            <span style={{ fontSize: 13, fontWeight: 500, color: 'var(--ink)' }}>{inv.title}</span>
            {inv.dateRange && <span style={{ fontSize: 10, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>{inv.dateRange}</span>}
          </div>
          {inv.summary && <p style={{ fontSize: 12, color: 'var(--ink-3)', lineHeight: 1.5, fontStyle: 'italic', margin: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{inv.summary}</p>}
          {linkedBooks.length > 0 && (
            <div style={{ display: 'flex', gap: 4, marginTop: 5, alignItems: 'center' }}>
              {linkedBooks.map(b => (
                <span key={b.id} style={{ display: 'flex', alignItems: 'center', gap: 3, fontSize: 10, color: b.color, fontStyle: 'italic' }}>
                  <div style={{ width: 5, height: 5, borderRadius: '50%', background: b.color }} />{b.title}
                </span>
              ))}
            </div>
          )}
        </div>
        <div style={{ textAlign: 'right', flexShrink: 0 }}>
          <span style={{ fontSize: 10, padding: '2px 8px', borderRadius: 10, background: ss.bg + '55', color: ss.color, fontFamily: 'var(--font-mono)', fontStyle: 'normal', display: 'block', marginBottom: 4 }}>{ss.label}</span>
          <span style={{ fontSize: 10, padding: '2px 8px', borderRadius: 10, background: invType.bg + '55', color: invType.color, fontFamily: 'var(--font-mono)', fontStyle: 'normal', display: 'block' }}>{invType.label}</span>
          {inv.tags?.length > 0 && <div style={{ fontSize: 10, color: 'var(--ink-4)', marginTop: 4, fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>{inv.tags.slice(0,3).map(t => `#${t}`).join(' ')}</div>}
        </div>
      </div>
    );
  }

  // Board card
  return (
    <div onClick={onClick}
      style={{ background: 'var(--paper-card)', border: '1px solid var(--paper-3)', borderTop: `3px solid ${invType.color}`, borderRadius: 10, padding: '14px 14px 12px', cursor: 'pointer', transition: 'box-shadow 0.12s', display: 'flex', flexDirection: 'column', gap: 8 }}
      onMouseEnter={e => e.currentTarget.style.boxShadow = 'var(--shadow-sm)'}
      onMouseLeave={e => e.currentTarget.style.boxShadow = 'none'}>
      <div style={{ display: 'flex', gap: 5, alignItems: 'center' }}>
        <span style={{ fontSize: 9, padding: '1px 7px', borderRadius: 8, background: ss.bg + '55', color: ss.color, fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>{ss.label}</span>
        {inv.dateRange && <span style={{ fontSize: 9, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>{inv.dateRange}</span>}
        <div style={{ flex: 1 }} />
        {linkedBooks.slice(0,3).map(b => <div key={b.id} title={b.title} style={{ width: 7, height: 7, borderRadius: '50%', background: b.color }} />)}
      </div>
      <div style={{ fontSize: 13, fontWeight: 500, color: 'var(--ink)', lineHeight: 1.4 }}>{inv.title}</div>
      {inv.summary && <p style={{ fontSize: 12, color: 'var(--ink-3)', lineHeight: 1.55, fontStyle: 'italic', margin: 0, display: '-webkit-box', WebkitLineClamp: 3, WebkitBoxOrient: 'vertical', overflow: 'hidden' }}>{inv.summary}</p>}
      {inv.tags?.length > 0 && (
        <div style={{ display: 'flex', gap: 4, flexWrap: 'wrap' }}>
          {inv.tags.slice(0, 4).map(tag => <span key={tag} style={{ fontSize: 9, padding: '1px 6px', borderRadius: 8, background: 'var(--paper-2)', color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>#{tag}</span>)}
        </div>
      )}
      {inv.actors?.length > 0 && (
        <div style={{ fontSize: 10, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>
          {inv.actors.length} actor{inv.actors.length !== 1 ? 's' : ''} · {inv.causes?.length || 0} cause{(inv.causes?.length || 0) !== 1 ? 's' : ''}
        </div>
      )}
    </div>
  );
}

// ── Main ─────────────────────────────────────────────────────────
export default function InvestigationView({
  investigations, books, events,
  invTypes, onUpdateInvTypes,
  onUpdate, onAdd, onDelete, onSwitchToTimeline,
}) {
  const [displayMode, setDisplayMode] = useState('board');
  const [filterType,   setFilterType]   = useState('all');
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterBook,   setFilterBook]   = useState('all'); // 'all' | bookId
  const [search, setSearch]             = useState('');
  const [activeCaseId, setActiveCaseId] = useState(null);
  const [editingInv, setEditingInv]     = useState(null);
  const [isNewInv, setIsNewInv]         = useState(false);
  const [managingTypes, setManagingTypes] = useState(false);

  // ── Filtering ─────────────────────────────────────────────────
  const filtered = investigations
    .filter(inv => filterType   === 'all' || inv.type   === filterType)
    .filter(inv => filterStatus === 'all' || inv.status === filterStatus)
    .filter(inv => filterBook   === 'all' || (inv.bookIds || []).includes(filterBook))
    .filter(inv => !search
      || inv.title.toLowerCase().includes(search.toLowerCase())
      || inv.tags?.some(tag => tag.includes(search.toLowerCase()))
      || inv.actors?.some(actor => actor.toLowerCase().includes(search.toLowerCase())));

  const activeCase = activeCaseId ? investigations.find(i => i.id === activeCaseId) : null;

  // ── Case page ────────────────────────────────────────────────
  if (activeCase) {
    return (
      <InvestigationCasePage
        inv={activeCase} books={books} events={events} invTypes={invTypes}
        onUpdate={onUpdate}
        onEdit={() => { setEditingInv(activeCase); setIsNewInv(false); }}
        onBack={() => setActiveCaseId(null)}
        onViewTimeline={tag => { setActiveCaseId(null); onSwitchToTimeline?.(tag); }}
      />
    );
  }

  const handleAdd = () => {
    setEditingInv({
      id: uuidv4(), title: '', type: invTypes[0]?.id || 'political', status: 'active',
      dateRange: '', actors: [], causes: [], bookIds: [], bookNotes: [],
      tags: [], summary: '', analysis: '',
      createdAt: new Date().toISOString(), updatedAt: new Date().toISOString(),
    });
    setIsNewInv(true);
  };

  // Board groups use live invTypes
  const boardGroups = invTypes
  .map(type => ({
    type,
    items: filtered.filter(item => item.type === type.id),
  }))
  .filter(group =>
    group.items.length > 0 || filterType === group.type.id
  );

  // Books that appear in at least one investigation
  const usedBookIds = [...new Set(investigations.flatMap(i => i.bookIds || []))];
  const usedBooks   = books.filter(b => usedBookIds.includes(b.id));

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>

      {/* Topbar */}
      <div style={{ padding: '12px 20px 10px', borderBottom: '1px solid var(--paper-3)', flexShrink: 0 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 10 }}>
          <div>
            <div style={{ fontSize: 15, fontWeight: 500, color: 'var(--ink)' }}>Investigation</div>
            <div style={{ fontSize: 11, color: 'var(--ink-3)', fontStyle: 'italic', marginTop: 1 }}>
              {investigations.length} case{investigations.length !== 1 ? 's' : ''} · {investigations.filter(i => i.status === 'active').length} active
            </div>
          </div>
          <div style={{ marginLeft: 'auto', display: 'flex', gap: 6, alignItems: 'center' }}>
            {/* View toggle */}
            <div style={{ display: 'flex', border: '1px solid var(--paper-3)', borderRadius: 7, overflow: 'hidden' }}>
              {[['board','⊞ Board'],['list','≡ List']].map(([mode, label]) => (
                <button key={mode} onClick={() => setDisplayMode(mode)}
                  style={{ padding: '5px 12px', fontSize: 11, border: 'none', borderRight: mode === 'board' ? '1px solid var(--paper-3)' : 'none', background: displayMode === mode ? 'var(--accent-light)' : 'transparent', color: displayMode === mode ? 'var(--accent)' : 'var(--ink-3)', cursor: 'pointer' }}>
                  {label}
                </button>
              ))}
            </div>
            <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search cases…"
              style={{ width: 170, padding: '6px 12px', fontSize: 12 }} />
            <button onClick={handleAdd}
              style={{ fontSize: 12, padding: '6px 16px', borderRadius: 7, background: 'var(--accent)', color: 'var(--paper-card)', border: 'none', cursor: 'pointer', whiteSpace: 'nowrap' }}>
              + Open case
            </button>
          </div>
        </div>

        {/* Filter bar */}
        <div style={{ display: 'flex', gap: 5, flexWrap: 'wrap', alignItems: 'center' }}>
          {/* Type pills */}
          <Pill active={filterType === 'all'} color="var(--ink-3)" bg="var(--paper-3)" onClick={() => setFilterType('all')}>All types</Pill>
          {invTypes.map(t => {
            const cnt = investigations.filter(i => i.type === t.id).length;
            if (!cnt) return null;
            return <Pill key={t.id} active={filterType === t.id} color={t.color} bg={t.bg} onClick={() => setFilterType(filterType === t.id ? 'all' : t.id)}>{t.label} {cnt}</Pill>;
          })}
          <button onClick={() => setManagingTypes(true)}
            style={{ fontSize: 10, color: 'var(--ink-4)', background: 'none', border: '1px solid var(--paper-3)', borderRadius: 5, padding: '2px 8px', cursor: 'pointer', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>
            manage types
          </button>

          <div style={{ width: 1, height: 14, background: 'var(--paper-3)' }} />

          {/* Status pills */}
          {['all','active','cold','closed'].map(s => (
            <Pill key={s} active={filterStatus === s}
              color={STATUS_STYLES[s]?.color || 'var(--ink-3)'}
              bg={STATUS_STYLES[s]?.bg || 'var(--paper-3)'}
              onClick={() => setFilterStatus(filterStatus === s ? 'all' : s)}>
              {s === 'all' ? 'All status' : STATUS_STYLES[s]?.label}
            </Pill>
          ))}

          <div style={{ width: 1, height: 14, background: 'var(--paper-3)' }} />

          {/* Book filter */}
          <Pill active={filterBook === 'all'} color="var(--ink-3)" bg="var(--paper-3)" onClick={() => setFilterBook('all')}>All books</Pill>
          {usedBooks.map(b => (
            <Pill key={b.id} active={filterBook === b.id} color={b.color} bg={b.color + '22'} onClick={() => setFilterBook(filterBook === b.id ? 'all' : b.id)}>
              <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4 }}>
                <span style={{ width: 6, height: 6, borderRadius: '50%', background: b.color, display: 'inline-block' }} />
                {b.title}
              </span>
            </Pill>
          ))}
        </div>
      </div>

      {/* Content */}
      <div style={{ flex: 1, overflowY: 'auto', padding: '16px 20px' }}>
        {filtered.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '60px 0', color: 'var(--ink-4)', fontStyle: 'italic', fontSize: 14, lineHeight: 1.7 }}>
            {search || filterType !== 'all' || filterStatus !== 'all' || filterBook !== 'all'
              ? 'No cases match your filters.'
              : 'No investigations yet.\nClick "+ Open case" to start your first.'}
          </div>
        ) : displayMode === 'board' ? (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(250px, 1fr))', gap: 16, alignItems: 'start' }}>
            {boardGroups.map(({ type, items }) => (
              <div key={type.id}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 7, marginBottom: 10 }}>
                  <div style={{ width: 10, height: 10, borderRadius: 2, background: type.color }} />
                  <span style={{ fontSize: 11, fontWeight: 600, color: type.color, letterSpacing: '0.06em', textTransform: 'uppercase', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>{type.label}</span>
                  <span style={{ fontSize: 10, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)' }}>{items.length}</span>
                </div>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                  {items.map(inv => (
                    <CaseCard key={inv.id} inv={inv} books={books} invTypes={invTypes} onClick={() => setActiveCaseId(inv.id)} compact={false} />
                  ))}
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            {filtered.map(inv => (
              <CaseCard key={inv.id} inv={inv} books={books} invTypes={invTypes} onClick={() => setActiveCaseId(inv.id)} compact />
            ))}
          </div>
        )}
      </div>

      {/* Modals */}
      {editingInv && (
        <InvestigationEditModal
          inv={editingInv} books={books} invTypes={invTypes} isNew={isNewInv}
          onSave={updated => {
            if (isNewInv) { onAdd(updated); setActiveCaseId(updated.id); }
            else onUpdate(updated);
          }}
          onDelete={onDelete}
          onClose={() => setEditingInv(null)}
        />
      )}
      {managingTypes && (
        <TypeManager
          title="Investigation types"
          types={invTypes}
          onUpdate={onUpdateInvTypes}
          onClose={() => setManagingTypes(false)}
          hasColor hasDash={false}
        />
      )}
    </div>
  );
}

function Pill({ active, color, bg, onClick, children }) {
  return (
    <button onClick={onClick} style={{
      fontSize: 10, padding: '3px 10px', borderRadius: 20,
      border: `1px solid ${active ? color : 'var(--paper-3)'}`,
      background: active ? bg + '44' : 'transparent',
      color: active ? color : 'var(--ink-3)',
      cursor: 'pointer', fontFamily: 'var(--font-mono)', fontStyle: 'normal',
    }}>{children}</button>
  );
}
